const orders = [{ id: 1, total: 100, lines: [{ qty: 2, price: 50 }] }];
function applyDiscount(order: any, percent: number) {
  order.total = order.lines.reduce((s, l) => s + l.qty * l.price, 0) * (1 - percent);
}
applyDiscount(orders[0], 0.1);

class ProfileService {
  updateProfile(user: any, changes: any) {
    Object.keys(changes).forEach(k => {
      user[k] = changes[k];
    });
  }
}
const alice = { name: 'Alice', role: 'user' };
new ProfileService().updateProfile(alice, { role: 'admin' });

